#!/usr/bin/env python3
# luxarch:worktree-submodules hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""A worktree's submodules: which the index records and are checked out, initialising them in a new
worktree, and whether the worktree's own submodule clones hold anything nothing else does, so that
removing the worktree (and its clones) loses no work.

Python 3.9 and the standard library only, like the hook that loads it.
"""

from __future__ import annotations

import os
import re
import subprocess
from pathlib import Path

from _worktree_git import git_env, net_limit, out, run, run_net


def gitlinks(path: Path) -> list[tuple[str, str]]:
    """(path, pinned commit) of every submodule the index at `path` records."""
    r = run(path, "ls-files", "--stage", "-z")
    found: list[tuple[str, str]] = []
    for rec in r.stdout.split("\0") if r.returncode == 0 else []:
        meta, _, rel = rec.partition("\t")
        f = meta.split()
        if rel and len(f) == 3 and f[0] == "160000":
            found.append((rel, f[1]))
    return found


def populated(sub: Path) -> bool:
    """A submodule checked out at `sub`: it has a `.git` of its own (a gitfile, a directory, a link)."""
    dotgit = sub / ".git"
    return dotgit.exists() or dotgit.is_symlink()


def _git_dir(
    gitdir: Path, *args: str, stdin: str | None = None, net: bool = False
) -> subprocess.CompletedProcess[str]:
    """git on one git dir. `net`: a call to a remote, with no prompt and `net_limit`'s timeout (a
    timeout reads as a failure)."""
    try:
        return subprocess.run(
            ["git", f"--git-dir={gitdir}", *args],
            capture_output=True,
            text=True,
            input=stdin if stdin is not None else "",
            env=git_env(GIT_TERMINAL_PROMPT="0") if net else git_env(),
            timeout=net_limit(False) if net else None,
        )
    except subprocess.TimeoutExpired:
        return subprocess.CompletedProcess(args, 124, "", "timed out")


def _inside(p: Path, folder: Path) -> bool:
    return folder in p.parents


def clones(modules: Path) -> list[Path]:
    """Every git dir under a `modules` folder: a submodule's clone (`modules/<name>`, the name may
    hold slashes) and, inside it, the clones of its own submodules (`<clone>/modules/<name>`)."""
    found: list[Path] = []
    for top, dirs, _files in os.walk(modules):
        here = Path(top)
        if (here / "HEAD").is_file() and (here / "objects").is_dir():
            found.append(here)
            dirs[:] = ["modules"] if "modules" in dirs else []
    return found


def _held_by(theirs: Path, shas: list[str]) -> bool:
    """Every commit in `shas` is on a ref (or HEAD) of the clone at `theirs`."""
    if not shas or not (theirs / "HEAD").is_file():
        return not shas
    # `--stdin` after `--not`: the commits read from stdin are not negated
    m = _git_dir(
        theirs,
        "rev-list",
        "--max-count=1",
        "--not",
        "--all",
        "--stdin",
        stdin="\n".join(shas) + "\n",
    )
    return m.returncode == 0 and not m.stdout.strip()


def _remote_tags(clone: Path, doomed: list[Path]) -> dict[str, str] | None:
    """{object: type} of what every remote of the clone holds a tag on, as each remote answers now
    (`ls-remote`, no prompt, a timeout), that the clone has too; None when a remote does not answer.
    A tag fetched from upstream on a commit no branch holds (a release whose branch was deleted, a
    SwiftPM pin) is upstream's, not this clone's. A remote is believed only when it is elsewhere: a
    URL that is a relative path, or a local path inside `doomed` (the worktree, the repository's
    worktree git dirs, every agent worktree), is this clone or one that can go the same way, and is
    skipped. A stated limit: an ssh URL to this machine (`localhost:/path`) is believed."""
    remotes = _git_dir(clone, "remote")
    if remotes.returncode != 0:
        return None
    shas: set[str] = set()
    for name in remotes.stdout.split():
        url = _git_dir(clone, "remote", "get-url", name).stdout.strip()
        local = url[len("file://") :] if url.startswith("file://") else url
        if not re.match(r"^[\w.+-]+(://|@[^/]*:|:)", local) or local.startswith(
            ("/", ".")
        ):
            if not local.startswith("/"):
                continue  # a relative path: nothing says where it resolves
            real = Path(os.path.realpath(local))
            if any(real == d or d in real.parents for d in doomed):
                continue
        r = _git_dir(clone, "ls-remote", "--tags", name, net=True)
        if r.returncode != 0:
            return None
        shas.update(line.split()[0] for line in r.stdout.splitlines() if line.strip())
    if not shas:
        return {}
    have = _git_dir(
        clone,
        "cat-file",
        "--batch-check=%(objectname) %(objecttype)",
        stdin="\n".join(sorted(shas)) + "\n",
    )
    return {
        w[0]: w[1]
        for w in (line.split() for line in have.stdout.splitlines())
        if len(w) == 2
    }


def unreached(clone: Path, theirs: Path, doomed: list[Path]) -> str:
    """Why the clone holds something nothing else does ("" when it holds nothing): a commit on any of
    its refs, its stash or a reflog that no remote branch it fetched reaches, no tag its remotes hold
    reaches and the main checkout's clone of the same submodule (`theirs`) does not hold on a ref of
    its own; or a ref on a tree or a blob (a tag can name one) that clone lacks. A stated limit: a
    remote branch is taken as holding what the clone last fetched of it."""
    r = _git_dir(clone, "rev-list", "--all", "--reflog", "--not", "--remotes")
    if r.returncode != 0:
        why = (r.stderr.strip().splitlines() or ["rev-list failed"])[0]
        return f"git cannot list its commits ({why})"
    shas = r.stdout.split()
    upstream: dict[str, str] | None = None
    asked = False  # one ls-remote round per clone, whatever it answered
    if shas and not _held_by(theirs, shas):
        upstream, asked = _remote_tags(clone, doomed), True
        tags = [t for t, kind in (upstream or {}).items() if kind in ("commit", "tag")]
        if tags:
            # `^<sha>` on stdin is negated; `--not` on the command line does not reach stdin
            r = _git_dir(
                clone,
                "rev-list",
                "--all",
                "--reflog",
                "--not",
                "--remotes",
                "--stdin",
                stdin="".join(f"^{t}\n" for t in tags),
            )
            shas = r.stdout.split() if r.returncode == 0 else shas
        if shas and not _held_by(theirs, shas):
            return (
                f"{len(shas)} commit(s) that no remote branch or tag holds, and the main "
                "checkout's clone does not hold them all"
            )
    refs = _git_dir(
        clone,
        "for-each-ref",
        "--format=%(objectname) %(objecttype) %(*objectname) %(*objecttype) %(refname)",
    )
    if refs.returncode != 0:
        return "git cannot list its refs"
    for line in refs.stdout.splitlines():
        w = line.split()
        kind = w[3] if len(w) == 5 else w[1] if len(w) >= 2 else ""
        obj = w[2] if len(w) == 5 else w[0] if w else ""
        if kind not in ("tree", "blob"):
            continue
        if (theirs / "HEAD").is_file() and (
            _git_dir(theirs, "cat-file", "-e", obj).returncode == 0
        ):
            continue
        if upstream is None and not asked:
            upstream, asked = _remote_tags(clone, doomed), True
        if upstream and (w[0] in upstream or obj in upstream):
            continue  # a tag its remote holds (an upstream key published as a blob)
        return f"{w[-1]} names a {kind} that neither a remote tag nor the main checkout's clone holds"
    return ""


def submodule_hold(path: Path, main: Path) -> tuple[str, list[Path]]:
    """Why the worktree's submodules keep it ("" when nothing does), and the `.git` files to unlink
    before its clones are deleted. Every check fails toward keeping: a submodule whose clone is not
    the worktree's own (`<git dir>/modules`), whose HEAD is not the pinned commit, or whose clones git
    cannot read keeps the worktree."""
    gitdir = Path(out(path, "rev-parse", "--absolute-git-dir") or path / ".git")
    modules = gitdir / "modules"
    links: list[Path] = []
    for rel, pinned in gitlinks(path):
        sub = path / rel
        if not populated(sub):
            continue
        dotgit = sub / ".git"
        if dotgit.is_symlink() or not dotgit.is_file():
            return f"submodule {rel} has a .git of its own that is not a gitfile", []
        own = out(sub, "rev-parse", "--absolute-git-dir")
        if not own or not _inside(Path(own), modules):
            return f"submodule {rel}'s clone is not under {modules}", []
        head = out(sub, "rev-parse", "--verify", "--quiet", "HEAD")
        if head != pinned:
            return (
                f"submodule {rel} is at {head[:8] or 'no commit'}, not the pinned {pinned[:8]}",
                [],
            )
        links.append(dotgit)
    if modules.is_symlink() or (modules.exists() and not modules.is_dir()):
        return f"{modules} is not a directory", []
    common = Path(
        out(main, "rev-parse", "--path-format=absolute", "--git-common-dir")
        or main / ".git"
    )
    found = clones(modules) if modules.is_dir() else []
    for clone in found:
        sub = clone.relative_to(modules)
        if any((clone / "worktrees").glob("*")):
            return f"submodule clone {sub} has linked worktrees of its own", []
        doomed = [
            Path(os.path.realpath(d))
            for d in (path, common / "worktrees", main / ".claude" / "worktrees")
        ]
        why = unreached(clone, common / "modules" / sub, doomed)
        if why:
            return f"submodule clone {sub}: {why}", []
    if found:
        borrower = _borrows_from(common, modules)
        if borrower:
            return (
                f"{borrower} borrows objects from this worktree's submodule clones",
                [],
            )
    return "", links


def _borrows_from(common: Path, modules: Path) -> str:
    """A clone anywhere in the repository's git dir whose `objects/info/alternates` names a path in
    `modules`: deleting `modules` would take objects that clone reads ("" when none does)."""
    try:
        files = list(common.rglob("objects/info/alternates"))
    except OSError:
        return str(common)
    for f in files:
        if modules in f.parents:
            continue
        try:
            lines = f.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            return str(f)
        for raw in lines:
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith('"') and line.endswith('"') and len(line) > 1:
                # git C-quotes a path it cannot write plainly
                line = (
                    line[1:-1]
                    .encode("latin-1", "backslashreplace")
                    .decode("unicode_escape")
                    .encode("latin-1", "replace")
                    .decode("utf-8", "replace")
                )
            # git reads a relative line against the objects directory, not objects/info
            alt = Path(os.path.realpath(f.parent.parent / line))
            real = Path(os.path.realpath(modules))
            if alt == real or real in alt.parents:
                return str(f.parents[2])
    return ""


def init_submodules(main: Path, target: Path) -> None:
    """Initialise in the worktree at `target` every submodule its index records that the main checkout
    has checked out and the worktree has not: a worktree is a checkout of tracked files only, and a
    gate that runs a submodule's scripts fails at once without it. One `git submodule update --init`
    with no prompt and a timeout (`LUXARCH_LAND_TIMEOUT`); on failure it prints the command to run.
    Only the top level: a nested submodule is initialised by hand."""
    want = [
        rel
        for rel, _ in gitlinks(target)
        if populated(main / rel) and not populated(target / rel)
    ]
    if not want:
        return
    r = run_net(target, "submodule", "update", "--init", "--", *want)
    if r.returncode == 0:
        print(f"initialised submodule(s) {', '.join(want)} in {target.name}")
        return
    said = (r.stdout + r.stderr).strip().splitlines()
    print(
        f"submodule init failed in {target.name} ({said[-1] if said else 'no output'}): run "
        f"`git submodule update --init -- {' '.join(want)}` there"
    )
